#!/usr/bin/env python3
import os
import time
BASE = "/workspace/notebooks/llama.cpp-ph2/ggml/src/ggml-cuda8"
BACKEND_H = os.path.join(BASE, "ggml-cuda8-ggml-backend.h")
BACKEND_CPP = os.path.join(BASE, "ggml-cuda8-ggml-backend.cpp")
PROBE_CPP = os.path.join(BASE, "ggml-cuda8-ggml-backend-probe.cpp")
CMAKE = os.path.join(BASE, "CMakeLists.txt")
BACKEND_H_TEXT = '// ggml/src/ggml-cuda8/ggml-cuda8-ggml-backend.h\n// G12A: minimal ggml_backend_t wrapper/probe for CUDA8.\n\n#ifndef GGML_CUDA8_GGML_BACKEND_H\n#define GGML_CUDA8_GGML_BACKEND_H\n\n#include "ggml-backend.h"\n\n#ifdef __cplusplus\nextern "C" {\n#endif\n\nggml_backend_t ggml_cuda8_ggml_backend_init(int device);\nint ggml_cuda8_ggml_backend_is_cuda8(ggml_backend_t backend);\nggml_backend_buffer_type_t ggml_cuda8_ggml_backend_get_default_buffer_type(ggml_backend_t backend);\n\n#ifdef __cplusplus\n}\n#endif\n\n#endif // GGML_CUDA8_GGML_BACKEND_H\n'
BACKEND_CPP_TEXT = '// ggml/src/ggml-cuda8/ggml-cuda8-ggml-backend.cpp\n// G12A: minimal ggml_backend_t wrapper/probe for CUDA8.\n\n#include "ggml-cuda8-ggml-backend.h"\n#include "ggml-cuda8-ggml-buffer.h"\n#include "ggml-backend-impl.h"\n\n#include <cstdio>\n#include <cstdlib>\n#include <cstring>\n\nstruct ggml_cuda8_ggml_backend_context {\n    int device;\n};\n\nstatic const char * cuda8_backend_get_name(ggml_backend_t backend) {\n    (void) backend;\n    return "CUDA8";\n}\n\nstatic void cuda8_backend_free(ggml_backend_t backend) {\n    if (backend == NULL) return;\n    ggml_cuda8_ggml_backend_context * ctx = (ggml_cuda8_ggml_backend_context *) backend->context;\n    if (ctx != NULL) std::free(ctx);\n    std::free(backend);\n}\n\nstatic ggml_backend_buffer_type_t cuda8_backend_get_default_buffer_type(ggml_backend_t backend) {\n    (void) backend;\n    return ggml_cuda8_ggml_buffer_type();\n}\n\nstatic struct ggml_backend_i cuda8_backend_i;\nstatic bool cuda8_backend_i_initialized = false;\n\nstatic void cuda8_backend_iface_init(void) {\n    if (cuda8_backend_i_initialized) return;\n    std::memset(&cuda8_backend_i, 0, sizeof(cuda8_backend_i));\n    cuda8_backend_i.get_name = cuda8_backend_get_name;\n    cuda8_backend_i.free = cuda8_backend_free;\n    cuda8_backend_i.get_default_buffer_type = cuda8_backend_get_default_buffer_type;\n    cuda8_backend_i_initialized = true;\n}\n\nextern "C" ggml_backend_t ggml_cuda8_ggml_backend_init(int device) {\n    cuda8_backend_iface_init();\n    ggml_cuda8_ggml_backend_context * ctx = (ggml_cuda8_ggml_backend_context *) std::malloc(sizeof(ggml_cuda8_ggml_backend_context));\n    if (ctx == NULL) return NULL;\n    ctx->device = device;\n    ggml_backend_t backend = (ggml_backend_t) std::malloc(sizeof(struct ggml_backend));\n    if (backend == NULL) { std::free(ctx); return NULL; }\n    std::memset(backend, 0, sizeof(*backend));\n    backend->iface = cuda8_backend_i;\n    backend->context = ctx;\n    return backend;\n}\n\nextern "C" int ggml_cuda8_ggml_backend_is_cuda8(ggml_backend_t backend) {\n    if (backend == NULL || backend->iface.get_name == NULL) return 0;\n    const char * name = backend->iface.get_name(backend);\n    return name != NULL && std::strcmp(name, "CUDA8") == 0;\n}\n\nextern "C" ggml_backend_buffer_type_t ggml_cuda8_ggml_backend_get_default_buffer_type(ggml_backend_t backend) {\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) return NULL;\n    if (backend->iface.get_default_buffer_type == NULL) return NULL;\n    return backend->iface.get_default_buffer_type(backend);\n}\n'
PROBE_CPP_TEXT = '// ggml/src/ggml-cuda8/ggml-cuda8-ggml-backend-probe.cpp\n// G12A smoke: minimal ggml_backend_t registration-shaped probe.\n\n#include "ggml-cuda8-ggml-backend.h"\n#include "ggml-cuda8-ggml-buffer.h"\n#include "ggml.h"\n#include "ggml-backend.h"\n#include "ggml-backend-impl.h"\n\n#include <cstdio>\n#include <cstring>\n#include <vector>\n\nstatic void setup_f32_vector(ggml_tensor & t, int64_t n, void * data) {\n    std::memset(&t, 0, sizeof(t));\n    t.type = GGML_TYPE_F32;\n    t.ne[0] = n; t.ne[1] = 1; t.ne[2] = 1; t.ne[3] = 1;\n    t.nb[0] = sizeof(float);\n    t.nb[1] = (size_t) n * sizeof(float);\n    t.nb[2] = t.nb[1];\n    t.nb[3] = t.nb[1];\n    t.data = data;\n}\n\nint main(int argc, char ** argv) {\n    (void) argc; (void) argv;\n    std::printf("ggml-cuda8-ggml-backend-probe: starting\\n");\n    ggml_backend_t backend = ggml_cuda8_ggml_backend_init(0);\n    if (backend == NULL) { std::fprintf(stderr, "backend init failed\\n"); return 1; }\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) { std::fprintf(stderr, "backend CUDA8 identity check failed\\n"); backend->iface.free(backend); return 1; }\n    const char * backend_name = backend->iface.get_name(backend);\n    std::printf("backend name: %s\\n", backend_name != NULL ? backend_name : "<null>");\n\n    ggml_backend_buffer_type_t buft = ggml_cuda8_ggml_backend_get_default_buffer_type(backend);\n    if (buft == NULL) { std::fprintf(stderr, "backend default buffer type is NULL\\n"); backend->iface.free(backend); return 1; }\n    std::printf("default buffer type: %s\\n", buft->iface.get_name(buft));\n    std::printf("alignment:           %zu\\n", buft->iface.get_alignment(buft));\n    std::printf("is_host:             %d\\n", buft->iface.is_host(buft) ? 1 : 0);\n\n    const int n = 64;\n    const size_t bytes = (size_t) n * sizeof(float);\n    ggml_backend_buffer_t buffer = buft->iface.alloc_buffer(buft, bytes);\n    if (buffer == NULL) { std::fprintf(stderr, "default buffer allocation failed\\n"); backend->iface.free(backend); return 1; }\n    if (!ggml_cuda8_ggml_buffer_is_cuda8(buffer)) { std::fprintf(stderr, "allocated buffer is not CUDA8\\n"); buffer->iface.free_buffer(buffer); backend->iface.free(backend); return 1; }\n    void * base = buffer->iface.get_base(buffer);\n    if (base == NULL) { std::fprintf(stderr, "buffer base is NULL\\n"); buffer->iface.free_buffer(buffer); backend->iface.free(backend); return 1; }\n    std::printf("allocated buffer size: %zu\\n", buffer->size);\n    std::printf("buffer base:           %p\\n", base);\n\n    ggml_tensor t;\n    setup_f32_vector(t, n, base);\n    if (buffer->iface.init_tensor(buffer, &t) != GGML_STATUS_SUCCESS) { std::fprintf(stderr, "init_tensor failed\\n"); buffer->iface.free_buffer(buffer); backend->iface.free(backend); return 1; }\n    std::vector<float> in(n), out(n, 0.0f);\n    for (int i = 0; i < n; ++i) in[i] = (float) i * 0.125f - 4.0f;\n    buffer->iface.set_tensor(buffer, &t, &in[0], 0, bytes);\n    buffer->iface.get_tensor(buffer, &t, &out[0], 0, bytes);\n    for (int i = 0; i < n; ++i) {\n        if (out[i] != in[i]) { std::fprintf(stderr, "roundtrip mismatch i=%d got=%f expected=%f\\n", i, out[i], in[i]); buffer->iface.free_buffer(buffer); backend->iface.free(backend); return 1; }\n    }\n    std::printf("backend default buffer set/get PASS\\n");\n    buffer->iface.free_buffer(buffer);\n    backend->iface.free(backend);\n    std::printf("ggml-cuda8-ggml-backend-probe: SUCCESS\\n");\n    return 0;\n}\n'
CMAKE_TARGET = '\n# ---------------------------------------------------------------------------\n# G12A minimal ggml_backend_t registration-shaped probe:\n#   - creates CUDA8 ggml_backend_t object\n#   - exposes CUDA8 default buffer type\n#   - allocates CUDA8 ggml_backend_buffer_t through backend default buft\n# ---------------------------------------------------------------------------\n\ncuda_add_executable(ggml-cuda8-ggml-backend-probe\n    ggml-cuda8-ggml-backend-probe.cpp\n)\n\ntarget_link_libraries(ggml-cuda8-ggml-backend-probe\n    ggml-cuda8-kernels\n    ${CUDA_LIBRARIES}\n)\n'

def backup(path):
    if os.path.exists(path):
        b = path + ".g12a-backup-" + str(int(time.time()))
        with open(path, "r") as f: data = f.read()
        with open(b, "w") as f: f.write(data)
        print("backup", b)

def write(path, text):
    with open(path, "w") as f: f.write(text)
    print("wrote", path)

write(BACKEND_H, BACKEND_H_TEXT)
write(BACKEND_CPP, BACKEND_CPP_TEXT)
write(PROBE_CPP, PROBE_CPP_TEXT)
backup(CMAKE)
with open(CMAKE, "r") as f: cm = f.read()
if "ggml-cuda8-ggml-backend.cpp" not in cm:
    if "ggml-cuda8-ggml-buffer-registry.cpp" in cm:
        cm = cm.replace("    ggml-cuda8-ggml-buffer-registry.cpp\n", "    ggml-cuda8-ggml-buffer-registry.cpp\n    ggml-cuda8-ggml-backend.cpp\n", 1)
    elif "ggml-cuda8-ggml-buffer.cpp" in cm:
        cm = cm.replace("    ggml-cuda8-ggml-buffer.cpp\n", "    ggml-cuda8-ggml-buffer.cpp\n    ggml-cuda8-ggml-backend.cpp\n", 1)
    else:
        raise SystemExit("could not find insertion point for ggml-cuda8-ggml-backend.cpp")
if "ggml-cuda8-ggml-backend-probe" not in cm:
    if not cm.endswith("\n"): cm += "\n"
    cm += CMAKE_TARGET
with open(CMAKE, "w") as f: f.write(cm)
print("patched", CMAKE)
print("")
print("G12A writer complete.")
